# -*- coding: utf-8 -*-
"""Release 1.72.539 GlossTitleQuote: the glossary link title uses the Hebrew gershayim. Generated by make_deploy539.py."""
RELS = ['inc/glossary-autolink.php']
HUNKS = {'inc/glossary-autolink.php': [(' - מילון נדל"ן">$1</a>\';', ' - מילון נדל״ן">$1</a>\';')]}


def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_539: no hunk on ' + rel)
    for old, new in HUNKS[rel]:
        n = txt.count(old)
        if n != 1:
            raise SystemExit('ashira_539: anchor x%d in the live %s: %r' % (n, rel, old.strip()[:70]))
        txt = txt.replace(old, new)
    return txt
